// components/OnboardingModal.tsx
import React, { useEffect, useState } from "react";

type Props = {
  open: boolean;
  onClose: () => void;
  onSubmit?: (data: { birthday: string; gender: "M" | "W" }) => void;
  variant?: "modal" | "inline" | "inline-sticky"; // ✅ sticky 추가
  stickyTop?: string; // 예: "20vh"
};

export default function OnboardingModal({
  open,
  onClose,
  onSubmit,
  variant = "modal",
  stickyTop = "18vh",
}: Props) {
  const [birthday, setBirthday] = useState("");
  const [gender, setGender] = useState<"M" | "W" | null>(null);
  const valid = birthday && gender;

  useEffect(() => {
    if (!open || variant !== "modal") return;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && onClose();
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, variant, onClose]);

  if (!open) return null;

  const cls =
    variant === "modal"
      ? "fixed inset-0 z-50 flex items-center justify-center"
      : variant === "inline"
      ? "absolute left-1/2 bottom-20 -translate-x-1/2 z-30"
      : // ✅ sticky: 섹션(부모) 기준으로 스크롤 동안 붙어있음
        `sticky z-30 left-1/2 -translate-x-1/2`;

  const style =
    variant === "inline-sticky" ? ({ top: stickyTop } as React.CSSProperties) : undefined;

  return (
    <div className={cls} style={style} role={variant === "modal" ? "dialog" : undefined} aria-modal={variant === "modal" || undefined}>
      {/* 풀스크린 모달일 때만 딤 */}
      {variant === "modal" && (
        <div className="absolute inset-0 bg-black/50 backdrop-blur-sm z-0" onClick={onClose} />
      )}

      {/* 카드 */}
      <div className="absolute bottom-20 left-1/2 -translate-x-1/2 z-30"></div>
      <div className="relative z-10 left-1/2 w-[90%] max-w-md rounded-3xl bg-white/95 p-6 shadow-xl text-center">
        <button aria-label="close" onClick={onClose} className="absolute right-3 top-3 rounded-full p-2 text-gray-400 hover:bg-gray-100">
          ✕
        </button>

        <h2 className="text-2xl font-extrabold tracking-tight text-gray-900">
          LENDY, <b>렌탈 구매 서비스</b>
        </h2>
        <p className="mt-3 text-sm leading-6 text-gray-500">
          첫 Lendy의 방문을 환영합니다. <br /> 더 좋은 서비스를 제공하기 위해 필수정보를 입력해주세요 :)
        </p>

        <label className="mt-5 block text-left text-sm font-medium text-gray-700">생년월일</label>
        <div className="mt-2 flex items-center gap-2 rounded-xl border px-3 py-2">
          <input type="date" className="w-full text-sm outline-none" value={birthday} onChange={(e) => setBirthday(e.target.value)} />
          <span className="opacity-60">📅</span>
        </div>

        <div className="mt-4 flex gap-3 justify-center">
          <button
            onClick={() => setGender("M")}
            className={`h-10 w-24 rounded-full border text-sm font-medium ${
              gender === "M" ? "bg-gray-900 text-white border-gray-900" : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            }`}
          >
            Men
          </button>
          <button
            onClick={() => setGender("W")}
            className={`h-10 w-24 rounded-full border text-sm font-medium ${
              gender === "W" ? "bg-emerald-300 text-white border-emerald-300" : "bg-gray-50 text-gray-700 hover:bg-gray-100"
            }`}
          >
            Women
          </button>
        </div>

        <button
          disabled={!valid}
          onClick={() => {
            if (!valid) return;
            onSubmit?.({ birthday, gender: gender! });
            onClose();
          }}
          className="mt-6 h-11 w-full rounded-full bg-gray-800 text-white text-sm disabled:bg-gray-300 disabled:cursor-not-allowed"
        >
          완료
        </button>
      </div>
    </div>
  );
}
